'use strict';
FLOWS.D={name:'Через личного агента',role:'Владелец + личный агент',entry:'Поручение в привычном агенте',title:'Поручите агенту.\nПроверьте результат.',lead:'Программа работает, партнёры приводят клиентов. Попросите агента подготовить выплаты — получите понятный реестр вместо обхода кабинетов.',cta:'Попробовать поручение',aha:'Готовый реестр с объяснением',paywall:'Владелец платит за принятый результат сервиса',steps:['Поручение','Делегирование','Готовый результат','Контроль','Тариф владельца','Агент партнёра'],goals:['Решить задачу без изучения кабинета','Дать агенту нужный доступ','Получить проверяемый результат','Утвердить именно проверенную версию','Понять стоимость агентного доступа','Получить свой статус через собственного агента'],friction:['Нужно помнить, в какой системе искать данные','Агенту могут достаться лишние полномочия','Красивый ответ не доказывает правильность сумм','Реестр изменился после подтверждения','Непрозрачная цена за вызовы и повторы','Чужой агент не должен видеть общий реестр'],patterns:['Intent → результат, привычный клиент','Ограниченная делегация с отзывом','Артефакт + источник + исключения','Подтверждение версии и ручной перевод','Платит владелец; модель тарифа ещё обсуждается','Личный scope, задача, ожидание, отмена']};
const agentState={granted:false,expiresAt:0,prepared:false,revision:1,approved:null,corrected:false,partnerGranted:false,partnerTask:'none',partnerTaskId:0,manualHandoff:false,manualSent:null};
const agentAllowed=()=>agentState.granted&&agentState.expiresAt>Date.now();
const agentTotal=()=>agentState.corrected?8400:9600;
function agentButton(text,action,kind='primary'){return button(text,'agent-'+action,kind)}
function agentAccess(){return agentAllowed()?'Доступ к задаче активен':agentState.granted?'Доступ истёк':'Доступ не выдан / отозван'}
function agentFrame(title,subtitle,body,role='Владелец Proofwall · личный агент'){return `<div class="agent-work"><div class="work-top"><div><span class="eyebrow">${role}</span><h1>${title}</h1><p class="lead">${subtitle}</p></div><span class="chip">${step+1} из 6 · демо</span></div>${body}</div>`}
function agentRows(){return [['Студия «Смысл»',4800],['Анна К.',agentState.corrected?1200:2400],['Медиа «Рост»',2400]]}
function agentArtifact(){return `<div class="artifact-heading"><span class="eyebrow">Реестр / август 2026 / версия ${agentState.revision}</span><span class="chip">${agentState.approved===agentState.revision?'Утверждён владельцем':'Черновик'}</span></div><div class="metric">${money(agentTotal())}</div><p>3 партнёра · ручные переводы до 5 сентября</p>${agentRows().map(([n,v])=>row(n,money(v))).join('')}<p class="tiny muted">Пример на 4 сентября. ${agentState.corrected?'Возврат у Анны: −1 200 ₽, новая версия требует проверки.':'Отдельно: 1 200 ₽ ещё на проверке, в сумму реестра не входят.'}</p>`}
function renderAgent(){
 if(step===0)return `<div class="hero"><div class="hero-copy"><span class="eyebrow">Новый вход / агент рядом с человеком</span><h1>Поручите агенту.<br>Проверьте результат.</h1><p class="lead">Тот же Круг, но начать можно с задачи. Личный агент подготовит реестр и объяснит цифры. Решение остаётся за вами.</p>${agentButton('Попробовать поручение','start')}<p class="tiny muted">Модель будущего взаимодействия. Сейчас — автономное HTML-демо.</p></div><div class="art"><div class="preview"><div class="preview-head"><b>Мой агент</b><span class="chip">Пример поручения</span></div><div class="preview-body"><div class="agent-message user-message">Подготовь выплаты партнёрам за август. Переводы сделаю сам до 5 сентября.</div><div class="agent-message"><b>Агент</b><p>Соберу реестр, выделю удержания и покажу, откуда взялась каждая сумма.</p><span class="tiny muted">Для начала нужен доступ к Proofwall.</span></div></div></div><div class="float-card"><span class="check">↗</span><div><strong>Задача → проверяемый результат</strong><div class="tiny muted">Человек видит суть, агент собирает детали</div></div></div></div></div><div class="benefits"><span>Можно отозвать доступ</span><span>Результат с источниками</span><span>Переводы остаются ручными</span></div>`;
 if(step===1)return agentFrame('Дайте доступ к одной задаче','Агенту достаточно чтения и подготовки черновика. Ему не нужен доступ ко всему бизнесу.',`<div class="two-col">${panel('Личный агент → Proofwall',`${row('Проект','Только Proofwall')}${row('Читать','Начисления и статусы выплат')}${row('Подготовить','Черновик реестра за август')}${row('Срок','15 минут · локальное демо')}<label class="agent-consent"><input id="agent-consent" type="checkbox" ${agentAllowed()?'checked':''}> Разрешаю чтение и подготовку этого реестра</label>${agentButton('Выдать доступ и продолжить','grant')}`)}${panel('Под вашим контролем',`<h2>Без переводов,<br>рассылок и изменения ставок.</h2><p>После выдачи доступа агент может читать и собирать черновик без подтверждения каждого шага. Утверждение готового реестра остаётся отдельным действием.</p><p>Отзыв прекращает дальнейшие действия агента. Вы сможете продолжить работу в обычном кабинете.</p><span class="chip">${agentAccess()}</span>`,'pale')}</div>`);
 if(step===2)return agentFrame(agentState.prepared?'Реестр готов к вашей проверке':'Агент знает задачу. Можно начинать.','Один артефакт, понятная сумма и отдельный список исключений.',`<div class="two-col">${panel('Результат агента',agentState.prepared?agentArtifact():`<div class="agent-message">Сверю оплаты, возвраты и уже отправленные суммы. Переводы не запускаю.</div><div class="actions">${agentButton('Подготовить реестр в демо','prepare')}</div><p>В этой модели используются фиксированные данные, а не реальный вызов MCP.</p>`,'pale')}${panel('Почему можно проверить результат',`<ol class="timeline"><li>Оплаты и начисления<small>${agentState.corrected?'Пример: 48 000 ₽ − 6 000 ₽ возврат = 42 000 ₽ × 20% = 8 400 ₽':'Пример: 48 000 ₽ оплачено × 20% = 9 600 ₽'}</small></li><li>Исключение видно отдельно<small>Ещё 1 200 ₽ удержаны до проверки и не включены</small></li><li>Каждая строка доступна владельцу<small>В реализации — ссылки на подтверждённые события</small></li></ol><span class="chip">${agentAccess()}</span><div class="actions">${agentButton('Повторить подготовку','prepare','secondary')}${agentButton('Проверить результат','inspect')}</div>`)}</div>`);
 if(step===3)return agentFrame('Проверили — утвердите эту версию','Агент подготовил реестр. Человек проверяет, скачивает и переводит деньги отдельно.',`<div class="two-col">${panel('Реестр владельца',agentState.prepared?`${agentArtifact()}<div class="actions">${agentButton('Утвердить версию '+agentState.revision,'approve')}${agentButton('Скачать утверждённый CSV','export','secondary')}</div>`:`<p>Сначала подготовьте результат. Пустой экран не означает готовый реестр.</p>${agentButton('Подготовить реестр','prepare')}`)}${panel('Попробуйте изменение условий',`<p>Если появился возврат, агент пересчитает реестр. Старое утверждение перестанет действовать.</p><div class="actions">${agentButton('Сымитировать возврат и пересчитать','revise','secondary')}${agentButton('Отозвать доступ','revoke','secondary')}${agentButton('Проверить истечение срока','expire','secondary')}</div><p><b>${agentAccess()}</b></p>${notice('Скачивание не означает отправку или зачисление денег. После отзыва/истечения агентный путь остановится; кабинет владельца остаётся доступен.')}<div class="actions">${agentButton('Продолжить вручную в A','manual','secondary')}${agentButton('Посмотреть тариф','pricing')}</div>`,'pale')}</div>`);
 if(step===4)return agentFrame('Агентный доступ — часть продукта','Платит владелец программы. Его партнёр не покупает тариф, чтобы узнать свой статус.',`<div class="two-col">${panel('Круг / агентный доступ',`<span class="eyebrow">Гипотеза упаковки</span><h2>Один продукт.<br>UI и агентный канал.</h2><p>Базовый ориентир демо A — 1 990 ₽/месяц. Доплата, лимиты задач и стоимость использования моделей для D пока не определены.</p>${row('Человек','Кабинет и ручной контроль')}${row('Его агент','Чтение и подготовка в рамках доступа')}${row('Деньги','Ручные выплаты до 5-го')}`,'pale')}${panel('Что проверять в пилоте',`<p>Сколько времени занимает принятый без ошибок реестр? Сколько раз человек исправляет результат? Сколько стоит завершённая задача с повторами?</p><p>Агент не должен превращать понятную подписку в непредсказуемый счёт за токены.</p><div class="actions">${agentButton('Перейти к агенту партнёра','partner')}</div>`)}</div>`);
 const task=agentState.partnerTask,labels={none:'Запрос ещё не создан',working:'Ожидаем ответ',canceled:'Запрос отменён',completed:'Ответ получен',denied:'Доступ отозван'};
 return agentFrame('У партнёра тоже есть свой агент','Теперь смотрим со стороны «Студии Смысл». Другой пользователь, другой доступ, только его данные.',`<div class="two-col">${panel('Личный агент партнёра',`<div class="agent-message user-message">Когда мне выплатят комиссию за август?</div><label class="agent-consent"><input id="partner-consent" type="checkbox" ${agentState.partnerGranted?'checked':''}> Разрешаю агенту читать только мой статус</label><div class="actions">${agentButton('Разрешить и спросить','ask')}</div><p class="tiny">Поручение агенту сервиса через A2A — проектная гипотеза. Подключённого endpoint в прототипе нет.</p>`)}${panel('Ответ в рамках задачи',`<span class="chip">${labels[task]}${agentState.partnerTaskId?' · задача '+agentState.partnerTaskId:''}</span>${task==='completed'?`<div class="metric">4 800 ₽</div>${row('Получатель','Студия «Смысл»')}${row('Срок','До 5 сентября')}${row('Статус выплаты','В реестре · ещё не отправлено')}<p>Источник: личная запись за август, версия демо1. Ответ агента получен — перевод денег ещё не выполнен.</p>`:`<p>В ответе будут сумма и статус только этого партнёра. Общий реестр владельца сюда не передаётся.</p>`}<div class="actions">${agentButton('Сымитировать ответ сервиса','response','secondary')}${agentButton('Отменить запрос','cancel','secondary')}${agentButton('Отозвать доступ партнёра','partner-revoke','secondary')}</div><div class="actions">${button('Сравнить A/B/C/D','compare')}</div>`,'pale')}</div>`,'Внешний партнёр · его личный агент');
}
function handleAgent(action){
 const a=action.replace('agent-','');
 if(['prepare','inspect','approve','export','revise'].includes(a)&&!agentAllowed()){toast('Доступ отсутствует или истёк. Выдайте его заново либо продолжите вручную.');render();return}
 switch(a){
 case'start':step=1;break;
 case'grant':if(!$('#agent-consent').checked){toast('Выберите, разрешаете ли доступ к задаче.');return}agentState.granted=true;agentState.expiresAt=Date.now()+15*60*1000;agentState.approved=null;step=2;break;
 case'prepare':agentState.prepared=true;toast('Демо: один реестр. Повтор не создаёт вторую копию.');break;
 case'inspect':if(!agentState.prepared){toast('Сначала подготовьте реестр.');return}step=3;break;
 case'approve':if(!agentState.prepared){toast('Нет подготовленного реестра.');return}agentState.approved=agentState.revision;toast('Утверждена версия '+agentState.revision+'. Переводы не запускались.');break;
 case'export':exportAgentRegistry();break;
 case'revise':if(!agentState.prepared){toast('Сначала подготовьте реестр.');return}agentState.corrected=true;agentState.revision++;agentState.approved=null;toast('Реестр пересчитан. Требуется проверка новой версии.');break;
 case'revoke':agentState.granted=false;agentState.approved=null;toast('Доступ агента отозван. Никакие переводы не выполнялись.');break;
 case'expire':agentState.expiresAt=0;agentState.approved=null;toast('Демо: срок доступа истёк.');break;
 case'manual':agentState.manualHandoff=true;variant='A';step=3;break;
 case'manual-approve':if(agentState.prepared)agentState.approved=agentState.revision;break;
 case'manual-export':exportAgentRegistry();break;
 case'manual-sent':if(agentState.approved===agentState.revision)agentState.manualSent=agentState.revision;else toast('Проверьте и утвердите текущий реестр.');break;
 case'manual-reset':agentState.manualHandoff=false;break;
 case'pricing':step=4;break;
 case'partner':step=5;break;
 case'ask':if(!$('#partner-consent').checked){toast('Партнёр должен разрешить доступ к собственному статусу.');return}agentState.partnerGranted=true;if(agentState.partnerTask==='working'){toast('Запрос уже выполняется.');return}agentState.partnerTask='working';agentState.partnerTaskId++;break;
 case'response':if(!agentState.partnerGranted||agentState.partnerTask!=='working'){toast('Нет активного разрешённого запроса. Поздний ответ не принят.');return}agentState.partnerTask='completed';break;
 case'cancel':if(agentState.partnerTask==='working')agentState.partnerTask='canceled';else toast('Сейчас нет выполняющегося запроса.');break;
 case'partner-revoke':agentState.partnerGranted=false;agentState.partnerTask='denied';break;
 }
 render();
}

function exportAgentRegistry(){if(!agentState.prepared||agentState.approved!==agentState.revision){toast('Сначала проверьте и утвердите текущую версию.');return}download('\uFEFFПартнёр;Период;Сумма_RUB;Версия;Статус\n'+agentRows().map(([n,v])=>`${n};2026-08;${v};${agentState.revision};${agentState.manualSent===agentState.revision?'Отправлено в демо':'Утверждено, не отправлено'}`).join('\n'),'n3-agent-registry-v'+agentState.revision+'.csv','text/csv;charset=utf-8')}
function renderManualAgentRegistry(){return workspace('Продолжите с тем же реестром','Владелец вернулся в кабинет. Данные и версия перенесены из агентного пути.',`<div class="two-col">${panel('Результат задачи из D',agentState.prepared?agentArtifact():'<p>Агент ещё не подготовил реестр. Можно вернуться к поручению или открыть отдельный пример A.</p>')}${panel('Теперь действует человек',`<p>Отзыв доступа агента не отнимает ваши права владельца. Проверьте текущий результат и утвердите его перед выгрузкой.</p><div class="actions">${agentButton('Утвердить вручную','manual-approve')}${agentButton('Скачать текущий CSV','manual-export','secondary')}${agentButton('Отметить отправку в демо','manual-sent','secondary')}</div><p>${agentState.manualSent===agentState.revision?'Отправлено в демо. Реальных переводов не было.':'Переводы за август делаете отдельно до 5 сентября.'}</p><div class="actions">${agentButton('Открыть отдельный пример A','manual-reset','secondary')}</div>`,'pale')}</div>`,'Владелец Proofwall · ручное продолжение D')}
